import pathlib

here = pathlib.Path(__file__).resolve().parent

renames = {
    "b_bold.md": "probe_bold.md",
    "c_marker.md": "probe_list_marker.md",
    "d_details.md": "probe_details_fold.md",
    "e_nocomment.md": "probe_drop_comment.md",
    "f_editcomment.md": "probe_edit_comment.md",
}
for old, new in renames.items():
    p = here / old
    if p.exists():
        p.rename(here / new)
        print("renamed", old, "->", new)

for gone in ("g_reorder.md", "cand_verbatim.md"):
    p = here / gone
    if p.exists():
        p.unlink()
        print("removed", gone)
